Según chatgpt, el problema estaría en usar .read y readBit/.write y writeBit en la cabecera del archivo .huf, intentamos recodificar la función que reconstruye el árbol para que use solo .read y desplazamiento de bits, pero sigue funcionando igual. Aun nos falta chequear recodeando el escribir cabecera de la misma manera pero por el momento esto es lo que tenemos.

package imple;
public class BitWriterImple implements BitWriter
{
private OutputStream f;
private int cdb;
private short bits;
@Override
public void using(OutputStream os)
{
this.f = os;
this.cdb = 0;
this.bits = 0;
}

@Override
public void writeBit(int bit) {
try {
bits |= (bit & 1) << (7 - cdb);
cdb++;
if (cdb == 8) {
f.write(bits);
cdb = 0;
bits = 0;
}
} catch (Exception e) {
throw new RuntimeException("Error escribiendo bit", e);
}
}

@Override
public void flush() {
try {
if (cdb > 0) {
int ceros = 8 - cdb;
for (int i = 0; i < ceros; i++) {
writeBit(0);
}
}
} catch (Exception e) {
throw new RuntimeException("Error escribiendo bit", e);
}
}
}

package imple;

import java.io.InputStream;

import huffman.def.BitReader;

public class BitReaderImple implements BitReader
{
private InputStream f;
private int cdb;
private int buffer;

@Override
public void using(InputStream is)
{
this.f = is;
this.cdb = 0;
this.buffer = 0;
}

@Override
public int readBit()
{
try {
if(cdb == 0)
{
buffer = f.read();
if(buffer == -1) {
return -1;
}
cdb = 8;
}

int ret = (buffer >> (cdb -1) & 1);
cdb--;
return ret;
}catch(Exception e) {
throw new RuntimeException("Error al leer bit", e);
}
}

@Override
public void flush()
{
cdb = 0;
buffer = 0;
}
}

