package imple;

import java.io.FileInputStream;
import java.io.FileOutputStream;
import java.util.ArrayList;
import java.util.List;

import huffman.def.BitWriter;

import huffman.def.Compresor;
import huffman.def.HuffmanInfo;
import huffman.def.HuffmanTable;
import huffman.util.HuffmanTreeMap;
import imple.Factory;

public class CompresorImple implements Compresor
{
private static int cmpIntInt(HuffmanInfo a, HuffmanInfo b)
{
int aux1=a.getN();
int aux2=b.getN();
return aux1-aux2;
}

@Override
public HuffmanTable[] contarOcurrencias(String filename)
{
HuffmanTable[] tabla=new HuffmanTable[256]; //crea un arreglo (array) de 256 posiciones,
//donde cada posición puede almacenar un objeto HuffmanTable
// Inicializo cada posición
for (int i = 0; i < 256; i++) {
tabla[i] = new HuffmanTable();
}

try (FileInputStream fis=new FileInputStream(filename))
{
int byteLeido;
while((byteLeido=fis.read())!=-1) //voy a recorrer el archivo siempre y cuando el byte leido sea !=-1
{
tabla[byteLeido].increment();//incremento el contador del caracter que representa el byte leido
}

return tabla; //Devuelvo la tabla
}
catch(Exception e)
{
throw new RuntimeException("Error al abrir archivo",e);
}
}

//Crea una lista enlazada ordenada ascendentemente por la cantidad de veces que aparecio el caracter.
@Override
public List<HuffmanInfo> crearListaEnlazada(HuffmanTable[] table)
{
List<HuffmanInfo> lista = new ArrayList<>();
for(int i = 0; i < 256; i++)
{
if(table[i].getN() > 0) //va a entrar siempre y cuando la cantidad de ocurrencia sea >0.
{
HuffmanInfo nuevo = new HuffmanInfo(); //creo una variable tipo HuffmanInfo
nuevo.setC(i); //seteo el caracter
nuevo.setN(table[i].getN());//seteo las veces que aparecio el caracter
nuevo.setLeft(null);
nuevo.setRight(null);
lista.add(nuevo);//agrega el elemento a la lista
}
}
lista.sort((a, b) -> cmpIntInt(a, b));//Ordená la lista lista comparando los objetos a y b
//según su campo N (frecuencia) usando cmpIntInt
return lista;
}

@Override
public HuffmanInfo convertirListaEnArbol(List<HuffmanInfo> list)
{
int i = 0;
while(list.size() > 1)
{
HuffmanInfo primero = list.remove(0);//Remueve el primer nodo
HuffmanInfo segundo = list.remove(0);//Remueve el segundo nodo
HuffmanInfo nuevo = new HuffmanInfo();//Crea un nuevo nodo
nuevo.setC(255+i);// le asigna como valor numerico 255+i
nuevo.setN(primero.getN() + segundo.getN());//la cantidad de ocurrencia va ser la suma de sus hijos.
nuevo.setLeft(primero);//seteo el hijo de la izquierda que es el primero que removi.
nuevo.setRight(segundo);//seteo el hijo de la derecha que es el segundo que removi.

// Lo que hace este bucle es buscar la posición correcta donde insertar el nuevo nodo (nuevo) para mantener la lista ordenada por frecuencia.
// list.get(j) obtiene el elemento actual de la lista.
// cmpIntInt(list.get(j), nuevo) compara las frecuencias(veces en que aparece el caracter).
// Si el elemento actual tiene frecuencia menor que la del nuevo (< 0), seguimos avanzando (j++).
// Cuando el while termina, j es la posición donde debe insertarse el nuevo nodo.
int j = 0;
while (j < list.size() && cmpIntInt(list.get(j), nuevo) < 0) {
j++;
}
list.add(j, nuevo); //Inserta el nuevo nodo en la posición j.
i++;
}

return list.get(0);//devuelve el primer nodo(osea la raiz del arbol)
}

//obs: el TAD HuffmanTree permite recorrer o visitar cada una de las hojas del arbol Huffman.

@Override
//su objetivo es asignar el código binario a cada carácter (o byte) del archivo original.

//HuffmanInfo root → la raíz del árbol de Huffman (ya construido en convertirListaEnArbol).
//HuffmanTable[] arr → el arreglo de frecuencias (256 posiciones), donde cada HuffmanTable guarda la
//cantidad de apariciones y (después de esto) el código binario de cada byte.
public void generarCodigosHuffman(HuffmanInfo root, HuffmanTable[] arr)
{
HuffmanTreeMap map = new HuffmanTreeMap(root); //crea un objeto auxiliar que recorre el árbol de Huffman(root)
//y construye una tabla de equivalencias entre cada
//carácter (byte), y su código binario de Huffman.

int[] ar = map.keys(); //Obtiene un array con todas las claves del mapa,osea todos los bytes(0–255)
// que realmente aparecen en el archivo.
for(int i = 0; i < map.size(); i++)
{
String codigo = map.get(ar[i]);//Obtiene el código Huffman (una cadena de '0' y '1') asociado a ese byte
arr[ar[i]].setCod(codigo); //Guarda ese código Huffman dentro de la tabla de frecuencias (HuffmanTable[]).
}
}

//se encarga de escribir la cabecera (header) del archivo .huf, es decir, toda la información que el descompresor va
//a necesitar para poder reconstruir el árbol de Huffman y decodificar los datos.
@Override
public void escribirEncabezado(String filename, HuffmanTable[] arr)
{
/*
1) 1 BYTE - CANTIDAD DE HOJAS
2) T REGISTROS PARA CADA HOJA, (ASCII/LONG. COD. HUFFMAN/COD. HUFFMAN)
3) 4 BYTES - LONGITUD ORIGINAL DEL
{ARCHIVO
4) LA INFO CODIFICADA
*/
try {
//Esto crea un objeto auxiliar que recorre el árbol de Huffman (root) y construye una tabla de equivalencias entre
//cada carácter (byte), y su código binario de Huffman.
FileOutputStream fos = new FileOutputStream(filename + ".huf");//preguntar profe
// preguntar profe por funcion size map
BitWriter bw = Factory.getBitWriter(); //crea un objeto que sabe escribir bits individuales en un archivo, usando el patrón
//Factory para obtener la implementación correcta.
bw.using(fos);
Byte contador = 0;
for(int i = 0; i < 256; i++)
{
if(arr[i].getN() > 0) {
contador++;
}
}
fos.write(contador); //ESCRIBIR EN ARCXHIVO CANTIDAD DE HOJAS

for(int i = 0; i < 256; i++)
{
if(arr[i].getN() > 0) {
Byte character = (byte)i;
String aux = arr[i].getCod();
fos.write(character);
fos.write((byte)aux.length());

for(int j = 0; j < aux.length(); j++)
{
char cb = aux.charAt(j);
int bit = cb-'0';
bw.writeBit(bit);
}

bw.flush();
}
}

long tam_arch_aux = new java.io.File(filename).length();
int tam_arch = (int)tam_arch_aux;
fos.write((tam_arch >>> 24) & 0xFF);
fos.write((tam_arch >>> 16) & 0xFF);
fos.write((tam_arch >>> 8) & 0xFF);
fos.write(tam_arch & 0xFF);
fos.close();
}catch(Exception e) {
throw new RuntimeException("Error creando archivo", e);
}

}

@Override
public void escribirContenido(String filename, HuffmanTable[] arr)
{
try (FileOutputStream fos=new FileOutputStream(filename+".huf",true); FileInputStream fis=new FileInputStream(filename);)
{

int byteLeido;
BitWriter bw=Factory.getBitWriter();
bw.using(fos);
while((byteLeido=fis.read())!=-1)
{
String codigo=arr[byteLeido].getCod();
for(int i=0; i<codigo.length(); i++)
{
char bit=codigo.charAt(i);
bw.writeBit((int)(bit-'0'));
}
}
bw.flush();
System.out.println("Termino el programa");
}
catch(Exception e)
{
