public class HuffmanTreeMap
{

private final Map<Integer,String> codeBySymbol=new HashMap<>();

public HuffmanTreeMap(HuffmanInfo root)
{
if(root==null)
{
throw new IllegalArgumentException("root no puede ser null");
}
buildCodeTable(root);
}

/**
* Devuelve el código Huffman del símbolo indicado o null si no existe.
* Por ejemplo, get('O') retornaría "01" para COMO COME COCORITO...
*/
public String get(int b)
{
return codeBySymbol.get(b);
}

// --- Internals ---

private static final class NodePath
{
final HuffmanInfo node;
final String path;

NodePath(HuffmanInfo node,String path)
{
this.node=node;
this.path=path;
}
}

private void buildCodeTable(HuffmanInfo root)
{
Deque<NodePath> stack=new ArrayDeque<>();
stack.push(new NodePath(root,""));

while(!stack.isEmpty())
{
NodePath np=stack.pop();
HuffmanInfo p=np.node;
String path=np.path;

boolean isLeaf=(p.getLeft()==null&&p.getRight()==null);

if(isLeaf)
{
// Convención para árbol de un solo nodo: asignar "0"
String code=path.isEmpty()?"0":path;

// Por símbolo (campo 'c'):
codeBySymbol.put(p.getC(),code);

// --- Si preferís indexar por 'n' (lo que llamaste "el n de una
// hoja"):
// codeBySymbol.put(p.getN(), code);
// y entonces get(int b) recibe ese 'n'
}
else
{
if(p.getRight()!=null)
{
stack.push(new NodePath(p.getRight(),path+"1"));
}
if(p.getLeft()!=null)
{
stack.push(new NodePath(p.getLeft(),path+"0"));
}
}
}
}

/** Retorna todos los símbolos/keys que se indexaron (uno por hoja). */
public int[] keys()
{
return codeBySymbol.keySet().stream().mapToInt(Integer::intValue).toArray();
}

/** Cantidad de hojas en el árbol (y por lo tanto, cantidad de códigos). */
public int size()
{
return codeBySymbol.size();
}
}

FUNCIONES RE-CODEADAS
@Override
public void escribirEncabezado(String filename, HuffmanTable[] arr)
{
try (FileOutputStream fos = new FileOutputStream(filename + ".huf"))
{
// 1) contar hojas
int hojas = 0;
for (int i = 0; i < 256; i++)
if (arr[i].getN() > 0)
hojas++;

fos.write(hojas);

// 2) escribir registros
for (int i = 0; i < 256; i++)
{
if (arr[i].getN() > 0)
{
byte character = (byte) i;
String code = arr[i].getCod();
int code_len = code.length();
int bytes = (code_len + 7) / 8;

fos.write(character); // ascii
fos.write(code_len); // longitud del código

// empaquetar bits del código en un buffer
byte[] buff = new byte[bytes];
int bitIndex = 0;

for (int j = 0; j < bytes; j++)
{
byte b = 0;
for (int bit = 7; bit >= 0 && bitIndex < code_len; bit--)
{
int v = code.charAt(bitIndex) - '0';
b |= (v << bit);
bitIndex++;
}
buff[j] = b;
}

fos.write(buff); // escribir el buffer completo
}
}

// 3) escribir tamaño original
long tam_arch_aux = new java.io.File(filename).length();
int tam_arch = (int) tam_arch_aux;

fos.write((tam_arch >>> 24) & 0xFF);
fos.write((tam_arch >>> 16) & 0xFF);
fos.write((tam_arch >>> 8) & 0xFF);
fos.write(tam_arch & 0xFF);
}
catch (Exception e)
{
throw new RuntimeException("Error creando archivo", e);
}
}

@Override
public int recomponerArbol(String filename, HuffmanInfo root)
{
try (FileInputStream fis = new FileInputStream(filename))
{
int totalBytes = 0;

// 1) leer cantidad de hojas
int hojas = fis.read();
totalBytes += 1;
System.out.println("CANTIDAD DE HOJAS: " + hojas);
for (int i = 0; i < hojas; i++)
{
int character = fis.read();
int code_len = fis.read();
totalBytes += 2;

int bytes = (code_len + 7) / 8;
byte[] buff = new byte[bytes];

int leidos = fis.read(buff);
if (leidos != bytes)
throw new RuntimeException("Error: header incompleto.");

totalBytes += bytes;

// reconstruir camino según los primeros code_len bits
HuffmanInfo nodo = root;

int bitIndex = 0;
for (int b = 0; b < bytes; b++)
{
for (int bit = 7; bit >= 0 && bitIndex < code_len; bit--)
{
int v = (buff[b] >> bit) & 1;
if (v == 0)
{
if (nodo.getLeft() == null)
nodo.setLeft(new HuffmanInfo());
nodo = nodo.getLeft();
}
else
{
if (nodo.getRight() == null)
nodo.setRight(new HuffmanInfo());
nodo = nodo.getRight();
}
bitIndex++;
}
}

nodo.setC(character);
nodo.setN(0);
nodo.setRight(null);
nodo.setLeft(null);
System.out.println((char)character + " -> reconstruido");
}

return totalBytes;
}
catch (Exception e)
{
throw new RuntimeException("Error al abrir archivo", e);
}
}

