In C#, can the Compare function be inline in such usage? I guess only the accept will invoke virtual call once, but all call of Compare is not longer virtual, which can save a lot of runtime.

using System;
using System.Runtime.CompilerServices;

// exists T where T : IComparable<T>. Array<T>
public interface IComparableArray
{
void Accept(IArrayAlgorithm algorithm);
}

public interface IArrayAlgorithm
{
void Invoke<T>(Span<T> values)
where T : IComparable<T>;
}

public sealed class ArrayBox<T> : IComparableArray
where T : IComparable<T>
{
private readonly T[] _values;

public ArrayBox(T[] values)
{
ArgumentNullException.ThrowIfNull(values);
_values = values;
}

public void Accept(IArrayAlgorithm algorithm)
{
ArgumentNullException.ThrowIfNull(algorithm);

algorithm.Invoke<T>(_values);
}

public ReadOnlySpan<T> Values => _values;
}

public sealed class InsertionSort : IArrayAlgorithm
{
public void Invoke<T>(Span<T> values)
where T : IComparable<T>
{
for (int i = 1; i < values.Length; i++)
{
T current = values[i];
int j = i - 1;

while (j >= 0 && Compare(values[j], current) > 0)
{
values[j + 1] = values[j];
j--;
}

values[j + 1] = current;
}
}

[MethodImpl(MethodImplOptions.AggressiveInlining)]
private static int Compare<T>(T left, T right)
where T : IComparable<T>
{
return left.CompareTo(right);
}
}

public sealed class ReverseAlgorithm : IArrayAlgorithm
{
public void Invoke<T>(Span<T> values)
where T : IComparable<T>
{
int left = 0;
int right = values.Length - 1;

while (left < right)
{
(values[left], values[right]) =
(values[right], values[left]);

left++;
right--;
}
}
}

public sealed class PrintAlgorithm : IArrayAlgorithm
{
public void Invoke<T>(Span<T> values)
where T : IComparable<T>
{
for (int i = 0; i < values.Length; i++)
{
if (i != 0)
{
Console.Write(", ");
}

Console.Write(values[i]);
}

Console.WriteLine();
}
}

public static class Program
{
public static void Main()
{
var intStorage = new ArrayBox<int>(
new[] { 5, 2, 9, 1, 3, 8, 4 });

var doubleStorage = new ArrayBox<double>(
new[] { 3.14, 2.71, 1.41, 0.57 });

var stringStorage = new ArrayBox<string>(
new[] { "pear", "apple", "orange", "banana" });

IComparableArray[] arrays =
{
intStorage,
doubleStorage,
stringStorage
};

IArrayAlgorithm sort = new InsertionSort();
IArrayAlgorithm reverse = new ReverseAlgorithm();
IArrayAlgorithm print = new PrintAlgorithm();

foreach (IComparableArray array in arrays)
{
Console.WriteLine("before sort:");
array.Accept(print);
array.Accept(sort);
Console.WriteLine("after sort:");
array.Accept(print);
array.Accept(reverse);
Console.WriteLine("after reverse:");
array.Accept(print);
Console.WriteLine();
}
}
}

