上記の考えたこと部の1のを使ってNES解像度のピクセル総数かどうかを比較しています。

コンソールログ
336 , 189

提示コード
全文です。ライブラリ未使用

#include <iostream>

int main(void)
{
int nesWidth = 256;
int nesHeight = 240;

int aspectRatio_x = 16;
int aspectRatio_y = 9;

for(int i = 0; i < 5000; i++)
{
int pixel = (aspectRatio_x * i) * (aspectRatio_y * i);

if(pixel >= (nesWidth * nesHeight))
{
std::cout<<(aspectRatio_x * i) << " , " << (aspectRatio_y * i)<<std::endl;
break;
}
}

return 0;
}

