public SSLContextBuilder createContextWithKeyStores(JksProperties jksProperties) {
SSLContextBuilder contextBuilder = SSLContextBuilder.create();
contextBuilder.setProtocol("TLS");
TrustStrategy acceptingTrustStrategy = (X509Certificate[] chain, String authType) -> true;
try {
for (Map.Entry<String, JksProperties.Credential> entry : jksProperties.getValues().entrySet()) {

String stringPath = entry.getValue().getPath();
String stringPass = entry.getValue().getPass();
char[] charArrayPass = getKeyPassword(stringPass);
KeyStore keyStore = getKeyStore(charArrayPass, stringPath);
contextBuilder.loadKeyMaterial(keyStore, charArrayPass);
contextBuilder.loadTrustMaterial(null, acceptingTrustStrategy);
}
} catch (NoSuchAlgorithmException | KeyStoreException | UnrecoverableKeyException | CertificateException |
IOException e) {
}
return contextBuilder;
}

char[] getKeyPassword(String keyPass) {
byte[] decodedPassword = Base64.getDecoder().decode(keyPass);
char[] keyPassword = new char[decodedPassword.length];
for (int i = 0; i < decodedPassword.length; i++) {
keyPassword[i] = (char) decodedPassword[i];
}
return keyPassword;
}

private KeyStore getKeyStore(char[] keyPassword, String keyPath)
throws IOException, KeyStoreException, NoSuchAlgorithmException, CertificateException {
final KeyStore keyStore = KeyStore.getInstance("JKS");
keyStore.load(Files.newInputStream(Paths.get(keyPath)), keyPassword);
return keyStore;
}

