from .models import *

def products_filter(request, tipo):
models_map = {
'katanas': Katana,
'haoris': Haori,
'armors': Armor,
'kabutos': Kabuto,
'masks': Mask,
'kunais': Kunai,
'shurikens': Shuriken,
}

models_with_size = ['haoris','armors','kabutos','masks']
empty = False
queryset = models_map[tipo].objects.select_related('product').all() if tipo else None

if not queryset:
empty = True
return {
'tipo': tipo,
'products': queryset,
'empty': empty,
}

search = request.GET.get('search')
if search:
queryset = queryset.filter(product__name__icontains=search)
if not queryset.exists():
empty = True

allowed_filters = ['top-rated', 'price-asc', 'price-desc', 'best-selling']
sort_by_filter = request.GET.get('sort_by_filter')
if sort_by_filter and sort_by_filter in allowed_filters:
if sort_by_filter == 'top-rated':
queryset = queryset.order_by('-product__rating')
elif sort_by_filter == 'price-asc':
queryset = queryset.order_by('product__price')
elif sort_by_filter == 'price-desc':
queryset = queryset.order_by('-product__price')
elif sort_by_filter == 'best-selling':
queryset = queryset.order_by('-product__sales')

size = request.GET.get('size')
if size and tipo in models_with_size:
queryset = queryset.filter(product__item_stocks__size=size).distinct()
if not queryset.exists():
empty = True

price_range = request.GET.get('range')
try:
if price_range and price_range != '10000':
price = float(price_range)
queryset = queryset.filter(product__price__lte=price)
if not queryset.exists():
empty = True
else:
queryset = queryset.filter(product__price__lte=10000)
except ValueError:
pass

return {
'tipo': tipo,
'products': queryset,
'empty': empty,
}

