def catalog(request):
tipos = ['katanas', 'shurikens', 'kunais', 'armors', 'haoris', 'kabutos', 'masks']
result = {}
total = 0
for tipo in tipos:
data = products_filter(request, tipo)
result[tipo] = data['products']
total += data['products'].count()
result['empty'] = total == 0
return render(request, 'catalog.html', result)

