Estoy desarrollando un sistema de menú desplegable basado en la estructura <ul>/<li> y eventos de hover (mouseover/mouseout) que controlan la visibilidad del submenú (.sub-menu.sm-X).

Implementé una paginación en JavaScript para estos submenús. El problema es que, al interactuar con los controles de paginación y cambiar de página, los estilos que fuerzo para mantener el menú abierto, hacen que el submenú quede pierda foco y se cierre inesperadamente.

El conflicto ocurre porque necesito "bloquear" el cierre del menú cuando el usuario hace clic en el control de paginación. Lo hago forzando la visibilidad y una clase de hover (sfHover) en el <li> padre (.has-sub)

Esta función se ejecuta en mousedown, mouseup y mouseover del control de paginación.

window.addEventListener('load', function () {

let activeSubmenu = null;

document.querySelectorAll(
'.sub-menu.sm-2, .sub-menu.sm-3, .sub-menu.sm-4, .sub-menu.sm-5, .sub-menu.sm-6, .sub-menu.sm-7, .sub-menu.sm-8, .sub-menu.sm-9, .sub-menu.sm-10, .sub-menu.sm-11, .sub-menu.sm-12, .sub-menu.sm-13, .sub-menu.sm-14, .sub-menu.sm-15, .sub-menu.sm-16, .sub-menu.sm-17, .sub-menu.sm-18, .sub-menu.sm-19, .sub-menu.sm-20, .sub-menu.sm-21, .sub-menu.sm-22, .sub-menu.sm-23'
).forEach(submenu => {

const allItems = Array.from(submenu.children);
const nonSubItems = allItems.filter(node => node.tagName === 'LI' && !node.classList.contains('sm-control-li'));
const pageSize = 5;
if (nonSubItems.length <= pageSize) return;

let currentPage = 0;
const totalPages = Math.ceil(nonSubItems.length / pageSize);
const parentLi = submenu.closest('li.has-sub');

// === Control de paginación
const controlLi = document.createElement('li');
controlLi.className = 'menu-item sm-control-li sm-not-close';
controlLi.style.listStyleType = 'none';
controlLi.style.padding = '0';
controlLi.style.margin = '0';
controlLi.style.minHeight = '10px';

const triangle = document.createElement('span');
triangle.className = 'scroll-triangle no-close-trigger sm-not-close sm-control-item';
triangle.style.cursor = 'pointer';
triangle.style.display = 'block';
triangle.style.textAlign = 'center';
triangle.style.padding = '5px 0';
triangle.style.userSelect = 'none';
triangle.style.background = 'rgb(249, 249, 249)';
triangle.innerHTML = '&#9660;';
controlLi.appendChild(triangle);
submenu.appendChild(controlLi);
submenu.setAttribute('tabindex', '0');

// === Apertura y cierre
function forceMenuOpen() {
if (activeSubmenu && activeSubmenu !== submenu) {
activeSubmenu.style.visibility = '';
activeSubmenu.style.opacity = '';
activeSubmenu.closest('li.has-sub')?.classList.remove('submenu-open-forced');
}
submenu.style.visibility = 'visible';
submenu.style.opacity = '1';
activeSubmenu = submenu;
parentLi?.classList.add('submenu-open-forced');
}

function restoreMenu(e) {
// Si el puntero sigue dentro del menú o de su control, no cierres
if (!e) return;
const to = e.relatedTarget;
if (submenu.contains(to) || parentLi.contains(to)) return;
submenu.style.visibility = '';
submenu.style.opacity = '';
parentLi?.classList.remove('submenu-open-forced');
if (activeSubmenu === submenu) activeSubmenu = null;
}

// === Hover con comprobación de relatedTarget ===
parentLi.addEventListener('mouseover', forceMenuOpen);
parentLi.addEventListener('mouseout', restoreMenu);
submenu.addEventListener('mouseover', forceMenuOpen);
submenu.addEventListener('mouseout', restoreMenu);

// === Paginación con rueda ===
submenu.addEventListener('wheel', e => {
e.preventDefault();
e.stopPropagation();
forceMenuOpen();
if (e.deltaY > 0) nextPage();
else previousPage();
});

// === Teclado ===
submenu.addEventListener('keydown', e => {
if (activeSubmenu === submenu) {
if (e.key === 'ArrowDown') {
e.preventDefault();
nextPage();
} else if (e.key === 'ArrowUp') {
e.preventDefault();
previousPage();
}
}
});

// === Clic en control ===
triangle.addEventListener('mousedown', e => {
e.preventDefault();
e.stopPropagation();
forceMenuOpen();
});

triangle.addEventListener('click', e => {
e.preventDefault();
e.stopPropagation();
forceMenuOpen();
if (triangle.innerHTML === '▲' || triangle.innerHTML === '&#9650;') previousPage();
else nextPage();
});

// === Paginación ===
function showPage() {
nonSubItems.forEach(li => li.style.display = 'none');

const start = currentPage * pageSize;
const end = start + pageSize;
const visibleItems = nonSubItems.slice(start, end);
visibleItems.forEach(li => li.style.display = '');

const lastVisibleItem = visibleItems[visibleItems.length - 1];
if (lastVisibleItem) submenu.insertBefore(controlLi, lastVisibleItem.nextSibling);
else submenu.appendChild(controlLi);

const isLastPage = (currentPage + 1) === totalPages;
const isFirstPage = currentPage === 0;

if (totalPages > 1) {
if (isLastPage) triangle.innerHTML = '&#9650;';
else if (isFirstPage) triangle.innerHTML = '&#9660;';
else triangle.innerHTML = '&#9661;';
} else {
triangle.innerHTML = '';
}
}

function nextPage() {
currentPage = (currentPage + 1 >= totalPages) ? 0 : currentPage + 1;
showPage();
}

function previousPage() {
currentPage = (currentPage - 1 < 0) ? totalPages - 1 : currentPage - 1;
showPage();
}

showPage();
});
});
