class Event(ABC):
event_type: Hashable

class EventHandler[E: Event]:

subs: dict[Hashable, dict[int, Callable[[E], None]]]
_next_id: int

def __init__(self) -> None:
self.subs = dict()
self._next_id = 0

def add_subscription(self, event_type: Hashable, callback: Callable[[E], None]) -> int:
self._next_id += 1
if not event_type in self.subs:
self.subs[event_type] = dict()
self.subs[event_type][self._next_id] = callback
return self._next_id

def post_event(self, event: E):
for callback in self.subs[event.event_type].values():
callback(event)

@dataclass(frozen=True, slots=True)
class CustomEvent(Event):
event_type: int
value: float

class CustomEventGenerator:

event_handler : EventHandler[CustomEvent]

def __init__(self) -> None:
self.event_handler = EventHandler()

def emit_event(self, value: float):
self.event_handler.post_event(CustomEvent(1, value))

def callback(event: CustomEvent):
print(f"the event value is {event.value}")

event_generator = CustomEventGenerator()
event_generator.event_handler.add_subscription(1, callback)

That makes the type checker happy, but each time I add an EventHandler to a class I have to parameterize it. This is tedious especially for classes that can generate several different events:

event_handler: EventHandler[ThisEvent | ThatEvent | AnotherEvent | YetAnotherEvent | AreYouKiddingMeEvent]

and because the EventHandler doesn't need to know which events it is handling.

I did try to make Event a protocol but that gives the same error.

@dataclass(frozen=True, slots=True)
class Event(Protocol):
event_type: Hashable

Is there a better way?

Is it better to define callbacks like this?

def callback(event: Event):
assert(isinstance(event, CustomEvent))
print(f"the event value is {event.value}")

It just seems silly to me to have to add runtime instructions to satisfy a static type checker.

