#include <iostream>
#include <raylib.h>
#include <box2d/box2d.h>
#include <glm/glm.hpp>

const int screenWidth = 1920;
const int screenHeight = 1080;

b2WorldDef worldDef;
b2WorldId world;

b2BodyDef playerDef;
b2BodyId playerBody;
b2Polygon playerShape;
b2ShapeDef playerShapeDef;
b2Transform playerTransform;
glm::vec2 playerPos = glm::vec2(0,0);
b2QueryFilter playerFilter;

b2BodyDef enemyDef;
b2BodyId enemyBody;
b2Polygon enemyShape;
b2ShapeDef enemyShapeDef;

b2ContactEvents contactEventList;

const float pixelScale = 0.01f;
void Init()
{
worldDef = b2DefaultWorldDef();
worldDef.gravity = (b2Vec2){0.0f,0.0f};
world = b2CreateWorld(&worldDef);
//std::cout << "world" << worldDef.gravity.y << std::endl;

//player
playerDef = b2DefaultBodyDef();
playerDef.type = b2_dynamicBody;
playerDef.position = (b2Vec2){0.0f,0.0f};
playerBody = b2CreateBody(world,&playerDef);
//playerShape = b2MakeBox(125,125);
playerShape = b2MakeBox(pixelScale * 125,pixelScale * 125);
playerShapeDef = b2DefaultShapeDef();
b2CreatePolygonShape(playerBody,&playerShapeDef,&playerShape);

//enemy
enemyDef = b2DefaultBodyDef();
//enemyDef.type = b2_staticBody;
enemyDef.type = b2_dynamicBody;
enemyDef.position = (b2Vec2){screenWidth / 2,0};
enemyBody = b2CreateBody(world,&enemyDef);
//enemyShape = b2MakeBox(125,125);
enemyShape = b2MakeBox(pixelScale * 125,pixelScale * 125);
enemyShapeDef = b2DefaultShapeDef();
b2CreatePolygonShape(enemyBody,&enemyShapeDef,&enemyShape);

contactEventList = b2World_GetContactEvents(world);
}

glm::vec2 force = glm::vec2(0,0);
void Player_Update()
{
const float speed = 200.0f;

if(IsKeyDown(KEY_W))
{
force.y -= speed;
}
if(IsKeyDown(KEY_S))
{
force.y += speed;
}
if(IsKeyDown(KEY_A))
{
force.x -= speed;
}
if(IsKeyDown(KEY_D))
{
force.x += speed;
}

//playerDef.position = (b2Vec2){playerPos.x,playerPos.y};
//b2Body_ApplyForceToCenter(playerBody,(b2Vec2){200,force.y},true);
b2Body_ApplyForceToCenter(playerBody,(b2Vec2){force.x,force.y},true);
}

void Collision()
{
for(int i = 0; i < contactEventList.beginCount; i++)
{
b2ContactBeginTouchEvent* beginEvent = contactEventList.beginEvents + i;
if(beginEvent->shapeIdA.index1 == playerBody.index1)
{
std::cout << "hit A" << std::endl;
}
else if(beginEvent->shapeIdB.index1 == playerBody.index1)
{
std::cout << "hit B" << std::endl;
}
}

}

int main()
{
InitWindow(screenWidth,screenHeight,"Hello World");
SetTargetFPS(60);

Init();

std::cout<<pixelScale * 125<<std::endl;
while(!WindowShouldClose())
{
BeginDrawing();
ClearBackground(BLACK);

b2World_Step(world,1.0f / 60.0f,8);
Collision();//衝突判定

Player_Update();

DrawRectangle(b2Body_GetPosition(playerBody).x,b2Body_GetPosition(playerBody).y,250,250,BLUE);

DrawRectangle(b2Body_GetPosition(enemyBody).x,b2Body_GetPosition(enemyBody).y,250,250,RED);

EndDrawing();
}

// ウィンドウを閉じる
CloseWindow();

return 0;
}

