function/1-2 注文書

/**注文書作成 */
function CreateOrderForm() {
try{
//情報取得関数から返り値を受け取る
if(!getInfo())return;
const { PDFfolder, ClientAndVender, TransactionInfo, Note, PayInfo, ExpirationDate } = getInfo();

//すでに出力用シートが存在する場合、削除する
if (ss.getSheetByName(`[注文書]出力用`)) { ss.deleteSheet(ss.getSheetByName(`[注文書]出力用`)) }

let format = ss.getSheetByName("注文書"); //フォーマット取得
let output = format.copyTo(ss).setName(`[注文書]出力用`) //コピーを出力用とする

/**------------------------入力情報の整形------------------------*/
let uuid = Utilities.getUuid(); //UUIDを生成
let client = ClientAndVender["発注者情報"] //発注者オブジェクト
//フォーマットに入力しやすいよう配列として整形
let clientInfo = [ //クライアント会社名と住所
[client["社名"] + "\n\n" + '〒' + client["郵便番号"] + '\n' + client["住所"] + '\n' + client["建物"]],
[client["電話番号"]], //電話番号
[client["代表"]] //代表者名
]
let vender = ClientAndVender["受注者情報"];//受注者オブジェクト
let venderInfo = [
[vender["社名"]], //受注側会社名
['〒' + vender["郵便番号"]], //住所
[vender["住所"]],
[vender["建物"]],
[vender["電話番号"]], //電話番号
["代表取締役 " + vender["代表"]] //代表者名
]
let total = TransactionInfo["注文内容"].reduce((acc, cur) => acc + cur["取引金額"], 0);//注文の合計金額を算出

let date = new Date();//今日のDateオブジェクト
let today = Utilities.formatDate(date, 'Asia/Tokyo', 'yyyy/MM/dd');//今日の日付にフォーマット

let note = Note["注文書"].split("\n")//備考を改行区切りで配列に

/**------------------------情報入力------------------------*/
output.getRange('G3').setValue(uuid) //G3にUUID
output.getRange('B4').setValue(vender["社名"]) //B4に受注側会社名
output.getRange('C7').setValue(TransactionInfo["件名"]) //C7に件名
output.getRange('G7:G9').setValues(clientInfo) //G7からG9に発注側会社情報
output.getRange('G13:G18').setValues(venderInfo) //G13からG16に受注側会社情報
output.getRange('C9').setValue(total) //C9に合計金額
output.getRange('G4').setValue(today) //G4に発効日

//備考が4行未満なら
if (note.length < 4) {
while (note.length !== 4) {note.push("")}//空白を加えて4行に揃える
}
//備考が4行より多ければ
if (note.length > 4) {
output.insertRowsAfter(14, note.length - 4)//差分の行数をシートに加える
}

let noteRow;//備考の行数を監視する
//備考配列をループ
for (let i = 0; i < note.length; i++) {
noteRow = 14 + i //備考を入力する行を算出
output.getRange(noteRow, 2).setValue([note[i]]) //1行ずつ備考を入力
}
output.getRange(14, 2, note.length, 3).setBorder(true, true, true, true, false, false);//備考を入力した範囲を罫線で囲む
noteRow += 5//注文内容を入力する行に影響しないように調整して渡す

let orderRow;//注文内容の入力行の監視
// 注文内容をループ
TransactionInfo["注文内容"].forEach(function (order, index) {
orderRow = noteRow + index;//注文内容の入力行を備考の行数と注文内容のインデックスから算出
let orderArr = Object.values(order);//オブジェクトを配列に直す
let orders = [orderArr.slice(0, 2).concat(["", ""]).concat(orderArr.slice(2, 5))]//間に空白を入れて微調整
output.getRange(`C${orderRow}:E${orderRow}`).merge();//注文内容入力行のセルを一部結合
output.getRange(orderRow, 2, 1, 7).setValues(orders).setBorder(true, true, true, true, true, true);//注文内容を入力し、罫線で囲む
})

SpreadsheetApp.flush();//入力内容を反映
PDFexport(output, PDFfolder, ClientAndVender["発注者情報"]["社名"], "注文書", orderRow)//PDF出力
}catch(e){
if(!exit(e))return
}
}

