// ばねの蓄積時間を加算する
springAccumulatedTime += Scene::DeltaTime();

while (0.005 <= springAccumulatedTime)
{
// ばねの力（変化を打ち消す方向）
double force = (-0.02 * springX);

// 画面を押しているときに働く力
if (cookieCircle.leftPressed())
{
force += 0.004;
}

// 速度に力を適用（減衰もさせる）
