int readint(char *s){
int i=0,ret=0;
while(*(s+i)>=48 && *(s+i)<=57){
ret*=10;
ret+=*(s+i)-48;
i+=1;
}
return ret;
}
void input_iarray(char* s,int* a,int n,int imax){
int aidx=0,i=0;
while(*(s+i)!=0 && i<imax){
if (*(s+i)<48 || *(s+i)>57){i++;}
else{
int bidx=i;
while(*(s+i)>=48 && *(s+i)<=57){
i++;
}
int t=0;
for(int j=bidx;j<i;j++){
t*=10;
t+=*(s+j)-48;
}
*(a+aidx++)=t;
}
}
if (aidx!=n)printf("n!=aidx aidx=%d\n",aidx);
}
int b_search(int* a,int n,int x){
int l=0,r=n;
while((r-l)>0){
int m=(r+l)/2;
if(*(a+m)<x){
l=m+1;
}else{
if(*(a+m)>=x && (m==0 || *(a+m-1)<x)){
return m;
}else{
r=m;
}
}
}
return -1;
}
void print_ivector(int* a,int n){
for(int i=0;i<n-1;i++){
printf("%d ",*(a+i));
}
printf("%d\n",*(a+n-1));
}
void qsort_1(int* a, int l, int r){
int left, right, d, temp;
if (l>=r)return;
d=*(a+l);
for(left=l,right=r;left<right;){
while(left<=right && a[left]<=d)left++;
while(left<=right && a[right]>d)right--;
if(left<right){
temp=a[left];
a[left]=a[right];
a[right]=temp;
}
}
temp=a[l];
a[l]=a[right];
a[right]=temp;
qsort_1(a,l,right-1);
qsort_1(a,right+1,r);
}

